ReplacementContent:
"                        <div className={`flex-1 min-w-0 h-8 rounded-full px-3 flex items-center transition-colors ${
                          isDark ? 'bg-[#0d1117] border border-gray-800' : 'bg-[#f1f3f4]'
                        }`}>
                          <input
                            type="text"
                            id="customer-name-input"
                            placeholder="Customer Name"
                            value={customerName}
                            onChange={e => setCustomerName(e.target.value)}
                            onFocus={() => {
                              if (posSettings.showVirtualKeyboard) {
                                setKeyboardTarget({ value: customerName, setValue: setCustomerName, type: 'text' });
                              }
                            }}
                            className={`w-full bg-transparent text-[10px] font-bold outline-none transition-colors ${
                              isDark ? 'text-gray-300 placeholder-gray-600' : 'text-slate-800 placeholder-slate-400'
                            }`}
                          />
                        </div>"

TargetContent:
"                        <div className={`flex-1 min-w-0 h-8 rounded-full px-3 flex items-center transition-colors ${
                          isTableSaved
                            ? (isDark ? 'bg-gray-900/40 border border-gray-800/40 opacity-60' : 'bg-slate-100 opacity-60')
                            : (isDark ? 'bg-[#0d1117] border border-gray-800' : 'bg-[#f1f3f4]')
                        }`}>
                          <input
                            type="text"
                            id="customer-name-input"
                            placeholder="Customer Name"
                            value={customerName}
                            onChange={e => setCustomerName(e.target.value)}
                            disabled={isTableSaved}
                            onFocus={() => {
                              if (isTableSaved) return;
                              if (posSettings.showVirtualKeyboard) {
                                setKeyboardTarget({ value: customerName, setValue: setCustomerName, type: 'text' });
                              }
                            }}
                            className={`w-full bg-transparent text-[10px] font-bold outline-none transition-colors ${
                              isTableSaved
                                ? 'cursor-not-allowed text-gray-500'
                                : (isDark ? 'text-gray-300 placeholder-gray-600' : 'text-slate-800 placeholder-slate-400')
                            }`}
                          />
                        </div>"
